    val HEIGHTS: FloatArray by lazy {
        val cells = (RAW_0 + "," + RAW_1).split(',')
        FloatArray(cells.size) { cells[it].toInt() / 100f }
    }

    /** Билинейная выборка высоты в мировых координатах. */
    fun heightAt(x: Float, z: Float): Float {
        val gx = ((x + HALF_EXTENT) / (2f * HALF_EXTENT) * (GRID - 1)).coerceIn(0f, (GRID - 1).toFloat())
        val gz = ((z + HALF_EXTENT) / (2f * HALF_EXTENT) * (GRID - 1)).coerceIn(0f, (GRID - 1).toFloat())
        val ix = gx.toInt()
        val iz = gz.toInt()
        val ix1 = minOf(ix + 1, GRID - 1)
        val iz1 = minOf(iz + 1, GRID - 1)
        val fx = gx - ix
        val fz = gz - iz
        val h00 = HEIGHTS[iz * GRID + ix]
        val h10 = HEIGHTS[iz * GRID + ix1]
        val h01 = HEIGHTS[iz1 * GRID + ix]
        val h11 = HEIGHTS[iz1 * GRID + ix1]
        val top = h00 * (1f - fx) + h10 * fx
        val bot = h01 * (1f - fx) + h11 * fx
        return top * (1f - fz) + bot * fz
    }
}
